// Helper function to get a random element from an array
function getRandomElement(array) {
    return array[Math.floor(Math.random() * array.length)];
}

// Content part rotator class
class ContentPartRotator {
    constructor(parts) {
        this.parts = [...parts];
    }
    getRandomIndex() {
        const maxIndex = Math.max(0, this.parts.length - 3);
        return Math.floor(Math.random() * (maxIndex + 1));
    }
    getNextPart() {
        if (this.parts.length <= 3) {
            return this.parts[0];
        }
        const index = this.getRandomIndex();
        const part = this.parts[index];
        this.parts.splice(index, 1);
        this.parts.push(part);
        return part;
    }
    reset(parts) {
        this.parts = [...parts];
    }
}

// Cache for content part rotators
const contentPartRotators = new Map();

function getContentPartRotator(category, subcategory, partType) {
    const key = `${category}:${subcategory}:${partType}`;
    if (!contentPartRotators.has(key)) {
        const parts = contentStructure[category][subcategory][partType];
        contentPartRotators.set(key, new ContentPartRotator(parts));
    }
    return contentPartRotators.get(key);
}

function generateStructuredContent(category, subcategory) {
    if (!contentStructure[category] || !contentStructure[category][subcategory]) {
        throw new Error(`Invalid category (${category}) or subcategory (${subcategory})`);
    }
    const structure = contentStructure[category][subcategory];
    const openingsRotator = getContentPartRotator(category, subcategory, 'openings');
    const endingsRotator = getContentPartRotator(category, subcategory, 'endings');
    const opening = openingsRotator.getNextPart();
    const ending = endingsRotator.getNextPart();
    return `${opening} ${ending}`;
}

function getCategories() {
    return Object.keys(contentStructure);
}

function getSubcategories(category) {
    if (!contentStructure[category]) {
        throw new Error(`Invalid category: ${category}`);
    }
    return Object.keys(contentStructure[category]);
}

function getRandomCategoryAndSubcategory() {
    const categories = getCategories();
    const category = getRandomElement(categories);
    const subcategories = getSubcategories(category);
    const subcategory = getRandomElement(subcategories);
    return { category, subcategory };
}

module.exports = {
    contentStructure,
    generateStructuredContent,
    getCategories,
    getSubcategories,
    getRandomCategoryAndSubcategory,
    getRandomElement
};